return {
  focus: {
    hook: "onEvent",
    eventType: "entityBleedingStart",
    promptOnPlayer: (H, actor, ctx) => {
      const entity = game.actors.get(ctx.payload.entityId);
      if (!H.condition.has(entity, "bleeding")) return false;
      return H.ask.confirm({
        title: "Drink Deep",
        bodyHtml: "Remove Bleeding from the Entity to grant Focus to all Hunters in your area?",
        noLabel: "Skip",
      });
    },
    applyOnGM: async (H, actor, ctx) => {
      const entity = game.actors.get(ctx.payload.entityId);
      if (!H.condition.has(entity, "bleeding")) return false;
      await H.condition.set(entity, "bleeding", false);
      const zone = H.zone.of(actor);
      for (const hunter of H.zone.huntersIn(zone)) await H.actions.focus(hunter, actor);
      await H.chat.post(`${actor.name} uses Drink Deep. Bleeding ends; all Hunters in ${zone} may Focus.`, actor);
    },
  },
};
